"""Offline HTML report. Dataset content is always escaped, never executed."""
from html import escape
from .core import summarize, total

def render(records):
    summary = summarize(records)
    cards = []
    for record in records:
        responses = ''.join('<section class="response"><h3>Response {}</h3><p>{}</p><p class="score">Weighted score: {}/20</p><small>{}</small></section>'.format(side, escape(record['responses'][side]), total(record['scores'][side]), escape(' · '.join('{} {}'.format(k, v) for k, v in record['scores'][side].items()))) for side in ('A', 'B'))
        evidence = ''.join('<li><b>{}</b> <q>{}</q><br>{}</li>'.format(escape(item['response']), escape(item['quote']), escape(item['reason'])) for item in record['evidence'])
        cards.append('<article id="{}"><div class="eyebrow">{} / {}</div><h2>{}</h2><p>{}</p><details><summary>Source of truth</summary><p>{}</p></details><div class="pair">{}</div><h3>Decision: {}</h3><p>{}</p><ul>{}</ul><p class="uncertainty"><b>Limit:</b> {}</p></article>'.format(escape(record['id']), escape(record['category']), escape(record['id']), escape(record['prompt']), 'Synthetic exercise · AI-assisted example', escape(record['source']), responses, escape(record['winner']), escape(record['rationale']), evidence, escape(record['uncertainty'])))
    navigation = '<nav aria-label="Cases">' + ''.join('<a href="#{}">{} · {}</a>'.format(escape(r['id']), escape(r['id']), escape(r['category'])) for r in records) + '</nav>'
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ReviewBench | Evaluation evidence</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#111518;color:#edf0ee;font:16px/1.65 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:64px 24px}header{padding-bottom:48px;border-bottom:1px solid #3b4546}h1{font-size:clamp(42px,7vw,76px);letter-spacing:-3px;line-height:1.1;margin:16px 0}h2{font-size:24px;line-height:1.35}h3{font-size:17px}.eyebrow,.score{color:#8ce0bd}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:12px}.lede{max-width:700px;color:#bdc9c7;font-size:20px}.stats{display:flex;flex-wrap:wrap;gap:24px;padding:24px 0}article{padding:40px 0;border-bottom:1px solid #3b4546}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:24px 0}.response{background:#1c2427;border:1px solid #3b4546;border-radius:12px;padding:24px}p{white-space:pre-wrap}small,.uncertainty{color:#b6c2c0}details{background:#1a2023;padding:16px;border-radius:8px}summary{cursor:pointer;color:#8ce0bd}li{margin-bottom:16px}footer{padding-top:40px;color:#b6c2c0}nav{display:flex;flex-wrap:wrap;gap:10px;padding:24px 0}nav a{font-size:13px;color:#b9ecd6;text-decoration:none;border:1px solid #3b4546;border-radius:24px;padding:7px 12px}nav a:hover,nav a:focus{background:#2c4940}article{scroll-margin-top:20px}@media(max-width:650px){.pair{grid-template-columns:1fr}main{padding:32px 18px}h1{letter-spacing:-1px}}@media print{body{background:white;color:black}.response,details{background:white;color:black}article{break-inside:avoid}}
</style></head><body><main><header><div class="eyebrow">ReviewBench / Evidence before preference</div><h1>Good judgment.<br>Visible reasoning.</h1><p class="lede">A small, inspectable evaluation workbench for editorial accuracy, instruction following, and design judgment.</p><div class="stats"><b>''' + str(summary['records']) + ''' synthetic cases</b><span>3 scoring dimensions</span><span>No API keys. No network calls.</span></div><p>These authored examples demonstrate a review method. They are not real model runs, client work, hiring-test answers, or measured evaluator performance.</p></header>''' + navigation + ''.join(cards) + '<footer>Scores help make judgments consistent; they do not replace checking the source. The validator checks structure and internal consistency, not whether a factual claim is true.</footer></main></body></html>'
